vec3 boxDim = vec3(.5, .5, .5);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = ( fragCoord - .5* iResolution.xy ) /iResolution.y;
   vec3 col = vec3(0.);
   fragColor = vec4(col,1.0);

   uv *= 1.8;
   float tt = fract(.2*iTime);

   vec3 camPos = vec3(0., 0., 4.5); 
   vec3 rayDir = normalize(vec3(uv, -1)); 
   float depth = 0.0;

   vec3 p = vec3(0);
   float closest;
   float offFinal;
   vec2 cellID;
   vec3 yy;
   for(int numIter = 0; numIter < 90; numIter++){
     p = camPos + depth * rayDir;

     p.yz *= rotation(PI/2.);

     float clampVal = 2.;
     float cV = clampVal;

     vec2 cellID_xz = clamp(round(p.xz),-clampVal,clampVal);
     p.xz = p.xz - cellID_xz;

     float d = 1E20;
     float nReach = 2.;

     for(float i = -nReach; i <= nReach; i++)
     for(float j = -nReach; j <= nReach; j++){
       vec2 tV = cellID_xz + vec2(i,j);
       if (abs(tV.x) <= cV && abs(tV.y) <= cV){
         float off = sin(TAU*(tt + hash12(tV)));
         float sdBF = sdBoxFrame(p - vec3(i,off,j), boxDim, .015);
         float sdB = sdBox(p - vec3(i,off,j), boxDim * .99);     
         if (min(sdBF, sdB) < d){
           if (sdBF < sdB){
             d = sdBF;
             closest = 0.;
             offFinal = off;
             cellID = cellID_xz;
           }
           else{
             d = sdB;
             closest = 1.;
             offFinal = off;
             cellID = cellID_xz;
           }
         }
       }
     }

     depth += d;
     if (d < .001 || depth > 20.0) break;
   }

   p -= vec3(0.,offFinal,0.);

   if (depth > 20.) col = vec3(0.);
   else if (closest == 1.){
    vec2 side;
    vec3 q = abs(p);
    if (q.x > q.y && q.x > q.z) side = p.yz;
    else if (q.y >= q.x && q.y > q.z) side = p.xz;
    else side = p.xy;
    float starAmount = 4. + 2.*floor(4. * hash12(cellID));
    vec2 star_uv = starAmount * side;
    vec2 starID = floor(star_uv);
    star_uv = fract(star_uv) - .5;
    float off = fract(323.23*sin(starID.x/10. + cellID.x) * 12.*sin(starID.y/10. + cellID.y));
    float star_rad = .15 + .15*sin(TAU*tt + TAU*off);
    float star = length(star_uv) - star_rad;
    col += smoothstep(0.,-fwidth(star),star);

   }
   else if (closest == 0.) col = vec3(1.);

   fragColor = vec4(col,1.0);

}

#define rotation(angle) mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

float PI = 3.14159;
float TAU = 2.*3.14159;

// Thanks IQ for the SDF functions!
// This version of the Box Frame function was faster than the other from here:
#define rotation(angle) mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

// https://www.shadertoy.com/view/3ljcRh
float dot2( in vec3 v ) { return dot(v,v); }
float sdBoxFrame( vec3 p, vec3 b, float e )
{
       p = abs(p  )-b;
  vec3 q = abs(p+e)-e;

  return sqrt(min(min(dot2(max(vec3(p.x,q.y,q.z),0.0)),
                      dot2(max(vec3(q.x,p.y,q.z),0.0))),
                      dot2(max(vec3(q.x,q.y,p.z),0.0)))) 
         +min(0.0,min(min( max(p.x,max(q.y,q.z)),
                           max(p.y,max(q.z,q.x))),
                           max(p.z,max(q.x,q.y))));
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

// https://www.shadertoy.com/view/4djSRW
float hash12(vec2 p)
{
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
